func _run_tests() -> void:
	var screen := await instantiate_main_scene()
	if not check("main_scene", screen != null, "La scena principale deve aprirsi senza errori"):
		return

	var bg := find_by_name(screen, "BackgroundDisplay") as BackgroundDisplay
	var box := find_by_name(screen, "DialogueBox") as PanelContainer
	if not check("nodes_exist", bg != null and box != null, "StoryScreen deve contenere BackgroundDisplay e DialogueBox"):
		return

	var bg_idx := bg.get_index()
	var box_idx := box.get_index()
	check("layer_order", bg_idx < box_idx, "BackgroundDisplay deve trovarsi prima di DialogueBox nell'albero per essere disegnato dietro")

	var dialogue_label := find_by_name(box, "DialogueLabel") as RichTextLabel
	if not check("dialogue_label", dialogue_label != null, "DialogueBox deve contenere DialogueLabel"):
		return

	check("text_waits_for_black", dialogue_label.text.is_empty(), "All'avvio, il dialogo non deve apparire prima che la transizione a nero sia conclusa")

	await wait_seconds(0.55)
	check("first_line_showing", not dialogue_label.text.is_empty(), "Dopo la transizione iniziale, la battuta deve comparire nella finestra di dialogo")
	check("bg_texture_set", bg.current_background.texture != null, "A transizione conclusa, lo sfondo deve avere una texture assegnata")

	if not check("has_change_scene", has_function(screen, "change_scene"), "StoryScreen deve avere la funzione change_scene()")):
		return

	var tex_icon: Texture2D = load("res://icon.svg")
	screen.call("change_scene", tex_icon, "Voce", "Testo dopo la dissolvenza", "crossfade", 0.4)
	await wait_frames(2)
	check("bg_transitioning", bg.is_transitioning(), "Durante change_scene(), BackgroundDisplay.is_transitioning() deve essere true")
	check("dialogue_cleared_during_trans", dialogue_label.text != "Testo dopo la dissolvenza", "Il nuovo testo non deve essere mostrato mentre la transizione è in corso")

	await wait_seconds(0.45)
	check("bg_not_transitioning", not bg.is_transitioning(), "A transizione conclusa, lo sfondo non deve più essere in transizione")
	check("new_bg_applied", bg.current_background.texture == tex_icon, "A transizione conclusa, la nuova immagine di sfondo deve essere visibile")
	check("new_text_shown", dialogue_label.text.contains("Testo dopo la dissolvenza"), "Solo al termine della dissolvenza il nuovo testo deve comparire a schermo")
",
