@onready var background_display: BackgroundDisplay = $BackgroundDisplay
@onready var dialogue_box: PanelContainer = $DialogueBox


func _ready() -> void:
	var bg_tex: Texture2D = load("res://assets/sprites/background.png")
	await change_scene(bg_tex, "Elena", "Dove... dove mi trovo?", "black", 0.4)


func change_scene(texture: Texture2D, speaker: String, text: String, transition_type: String = "crossfade", duration: float = 0.5) -> void:
	if dialogue_box:
		dialogue_box.clear()

	if background_display:
		if transition_type == "black":
			await background_display.transition_through_black(texture, duration)
		else:
			await background_display.crossfade_to(texture, duration)

	if dialogue_box:
		dialogue_box.show_line(speaker, text)
